/* Para: kasa-banka hesapları, hareketler, virman, banka ekstresi eşleştirme, POS, nakit akışı; çek-senet; krediler; gelir-gider, demirbaş, projeler */
(function () {
  const { $, $$, esc, money, icon } = CS;

  /* ================= KASA VE BANKA ================= */
  const FTABS = [['acc', 'Hesaplar', 'finance'], ['moves', 'Hesap hareketleri', 'finance/moves'], ['transfer', 'Virman', 'finance/transfer'], ['bank', 'Banka ekstresi eşleştir', 'finance/bank'], ['pos', 'POS tahsilatları', 'finance/pos'], ['flow', 'Nakit akışı', 'finance/flow']];
  CS.mod('finance', {
    title: 'Kasa ve banka',
    render(page, prm) {
      const sub = prm._[0] || 'acc';
      if (sub === 'a') return accDetail(page, CS.account(prm._[1]));
      const body = CS.head(page, 'Kasa ve banka', CS.can('finance', 'e') ? CS.btn('Hesap ekle', 'add', 'primary', 'plus') + CS.btn('Virman', 'vir', '', 'swap') + CS.btn('Para giriş / çıkış', 'io', '', 'wallet') : '', FTABS, sub);
      CS.bind(page, { add: () => accForm(), vir: () => CS.go('finance/transfer'), io: () => ioForm() });
      ({ acc, moves, transfer, bank, pos, flow })[sub](body);
    }
  });
  function acc(body) {
    const groups = CS.groupBy(CS.db.accounts.filter((a) => !a.closed), (a) => a.type);
    body.innerHTML = `<div class="kpis">${Object.entries(CS.ACC_TYPES).filter(([k]) => groups[k]).map(([k, l]) => CS.kpi(l, money(CS.sum(groups[k], (a) => CS.accBalance(a.id))), groups[k].length + ' hesap', k === 'kasa' ? 'hl' : '')).join('')}</div><div id="at"></div>`;
    CS.table($('#at', body), { rows: CS.db.accounts, search: false, cols: [{ l: 'Hesap', v: (a) => a.name, f: (a) => `<b>${esc(a.name)}</b>${a.closed ? ' <span class="pill">Kapalı</span>' : ''}<small>${esc(CS.ACC_TYPES[a.type])}${a.bank ? ' · ' + esc(a.bank) : ''}${a.iban ? ' · ' + esc(a.iban) : ''}</small>` }, { l: 'Şube', v: (a) => CS.byId('branches', a.branchId)?.name || '' }, { l: 'Döviz', v: (a) => a.currency || '₺' }, { l: 'Bu ay giriş', a: 'r', v: (a) => mSum(a, 1), f: (a) => `<span class="pos">${CS.fmt2(mSum(a, 1))}</span>` }, { l: 'Bu ay çıkış', a: 'r', v: (a) => mSum(a, -1), f: (a) => `<span class="neg">${CS.fmt2(-mSum(a, -1))}</span>` }, { l: 'Bakiye', a: 'r', v: (a) => CS.accBalance(a.id), f: (a) => `<b class="${CS.accBalance(a.id) < 0 ? 'neg' : ''}">${money(CS.accBalance(a.id), a.currency)}</b>${a.type === 'kart' && a.limit ? `<small>Kalan limit ${CS.fmt2(CS.num(a.limit) + CS.accBalance(a.id))}</small>` : ''}` }], onRow: (a) => CS.go('finance/a/' + a.id), actions: () => (CS.can('finance', 'e') ? CS.actBtn('edit', 'Düzenle', 'edit') : ''), onAct: (x, a) => accForm(a) });
  }
  const mSum = (a, s) => CS.sum(CS.db.accMoves.filter((m) => m.accId === a.id && m.date.slice(0, 7) === CS.today().slice(0, 7) && Math.sign(m.amt) === s), 'amt');
  function accForm(a) {
    const f = CS.form([{ k: 'type', l: 'Hesap türü', t: 'select', opts: Object.entries(CS.ACC_TYPES) }, { k: 'name', l: 'Hesap adı', req: true }, { k: 'bank', l: 'Banka' }, { k: 'branchName', l: 'Banka şubesi' }, { k: 'iban', l: 'IBAN / hesap no', w: 'full' }, { k: 'currency', l: 'Döviz', t: 'select', opts: CS.CURRENCIES }, { k: 'opening', l: 'Açılış bakiyesi', t: 'money' }, { k: 'limit', l: 'Kredi kartı limiti', t: 'money' }, { k: 'cutDay', l: 'Hesap kesim günü', t: 'number' }, { k: 'commission', l: 'POS komisyon %', t: 'number' }, { k: 'settleDays', l: 'POS valör (gün)', t: 'number' }, { k: 'settleAcc', l: 'POS aktarım hesabı', t: 'select', opts: CS.accOptions(['banka'], '—') }, { k: 'branchId', l: 'Şube', t: 'select', opts: CS.db.branches.map((b) => [b.id, b.name]) }, { k: 'closed', l: 'Hesap kapalı', t: 'check' }], a || { type: 'banka', currency: '₺', branchId: CS.branchId });
    CS.modal({ title: a ? 'Hesap düzenle' : 'Yeni hesap', body: f, buttons: [...(a && CS.can('finance', 'd') ? [{ label: 'Sil', kind: 'danger', onClick: () => { if (CS.db.accMoves.some((m) => m.accId === a.id)) { CS.toast('Hareket görmüş hesap silinemez; “Hesap kapalı” olarak işaretleyin.', 'bad'); return false; } CS.db.accounts = CS.db.accounts.filter((x) => x !== a); CS.save(); CS.route(); } }] : []), { label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; if (a) Object.assign(a, v); else CS.db.accounts.push({ id: 'acc_' + CS.uid(), ...v }); CS.log('Hesap kaydedildi', v.name); CS.save(); CS.route(); } }] });
  }
  function ioForm(accId, dir = 'out') {
    const f = CS.form([{ k: 'dir', l: 'İşlem', t: 'select', opts: [['out', 'Para çıkışı'], ['in', 'Para girişi']] }, { k: 'accId', l: 'Hesap', t: 'select', opts: CS.accOptions(null) }, { k: 'amount', l: 'Tutar', t: 'money', req: true }, { k: 'date', l: 'Tarih', t: 'date', def: CS.today() }, { k: 'category', l: 'Kategori', t: 'select', opts: [''].concat(CS.db.expenseCats, CS.db.incomeCats, ['Ortak cari / sermaye', 'Kredi kullanımı', 'Diğer']) }, { k: 'projectId', l: 'Proje', t: 'select', opts: CS.projOptions() }, { k: 'desc', l: 'Açıklama', w: 'full' }], { accId, dir });
    CS.modal({ title: 'Para giriş / çıkış', body: f, buttons: [{ label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; CS.addAccMove({ accId: v.accId, amt: v.dir === 'in' ? v.amount : -v.amount, date: v.date, desc: v.desc || v.category || 'Hesap hareketi', kind: v.dir === 'in' ? 'gelir' : 'gider', category: v.category, projectId: v.projectId }); CS.log('Hesap hareketi', money(v.amount)); CS.save(); CS.route(); } }] });
  }
  const KINDS = { tahsilat: 'Tahsilat', odeme: 'Ödeme', gider: 'Gider', gelir: 'Gelir', virman: 'Virman', sayim: 'Kasa farkı', cek: 'Çek / senet', kredi: 'Kredi', maas: 'Personel' };
  function moveTable(el, rowsFn, showAcc = true, withBal) {
    let tbl; const st = { acc: '', kind: '' }; el.innerHTML = '<div class="rng" style="margin-bottom:10px"></div><div class="mt"></div>';
    const rows = (a, b) => { let L = CS.db.accMoves.filter((m) => m.kind !== 'info' && m.date >= a && m.date <= b && (!st.acc || m.accId === st.acc) && (!st.kind || m.kind === st.kind)); L = rowsFn ? L.filter(rowsFn) : L; L.sort((x, y) => (x.date + x.at).localeCompare(y.date + y.at)); if (withBal) { let run = CS.num(withBal.opening) + CS.sum(CS.db.accMoves.filter((m) => m.accId === withBal.id && m.date < a), 'amt'); L = L.map((m) => ({ ...m, run: (run += m.amt) })); } return L.reverse(); };
    const r = CS.dateRange($('.rng', el), (a, b) => tbl.redraw(rows(a, b)));
    tbl = CS.table($('.mt', el), {
      rows: rows(...r.get()), tools: `${showAcc ? `<select class="fa" aria-label="Hesap"><option value="">Tüm hesaplar</option>${CS.accOptions(null).map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join('')}</select>` : ''}<select class="fk" aria-label="İşlem"><option value="">Tüm işlemler</option>${Object.entries(KINDS).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select><button class="btn fx">${icon('down', 15)} Excel</button>`,
      cols: [{ l: 'Tarih', k: 'date', f: (m) => CS.date(m.date) }, ...(showAcc ? [{ l: 'Hesap', v: (m) => CS.account(m.accId)?.name || '' }] : []), { l: 'Açıklama', k: 'desc', f: (m) => esc(m.desc) + (m.cid ? `<small><a href="#contacts/${m.cid}">${esc(CS.contactName(m.cid))}</a></small>` : '') + (m.image ? ' <span class="pill">Belge görseli</span>' : '') }, { l: 'Tür', v: (m) => KINDS[m.kind] || m.kind || '', f: (m) => esc(KINDS[m.kind] || m.kind || '') + (m.category ? `<small>${esc(m.category)}</small>` : '') }, { l: 'Giriş', a: 'r', v: (m) => (m.amt > 0 ? m.amt : 0), f: (m) => (m.amt > 0 ? `<span class="pos">${CS.fmt2(m.amt)}</span>` : '') }, { l: 'Çıkış', a: 'r', v: (m) => (m.amt < 0 ? -m.amt : 0), f: (m) => (m.amt < 0 ? `<span class="neg">${CS.fmt2(-m.amt)}</span>` : '') }, ...(withBal ? [{ l: 'Bakiye', a: 'r', v: (m) => m.run, f: (m) => CS.fmt2(m.run) }] : [])],
      actions: (m) => (m.image ? CS.actBtn('img', 'Belgeyi gör', 'eye') : '') + (CS.can('finance', 'd') && ['gider', 'gelir', 'virman', 'sayim', 'tahsilat', 'odeme'].includes(m.kind) ? CS.actBtn('del', 'Sil', 'trash', 'danger') : ''),
      onAct: (a, m) => { if (a === 'img') CS.modal({ title: m.desc, body: `<img src="${m.image}" style="max-width:100%">` }); if (a === 'del') CS.confirm('Hareket (ve bağlı cari/virman kaydı) silinsin mi?', () => { CS.removeAccMovesByRef(m.ref || m.id); CS.db.accMoves = CS.db.accMoves.filter((x) => x.id !== m.id); if (m.ref) CS.removeLedgerByRef(m.ref); CS.log('Hesap hareketi silindi', m.desc); CS.save(); CS.route(); }); },
      foot: (rs) => `<tr><td colspan="${showAcc ? 4 : 3}">${rs.length} hareket</td><td class="r">${CS.fmt2(CS.sum(rs.filter((m) => m.amt > 0), 'amt'))}</td><td class="r">${CS.fmt2(-CS.sum(rs.filter((m) => m.amt < 0), 'amt'))}</td>${withBal ? '<td></td>' : ''}<td></td></tr>`
    });
    const fa = $('.fa', el); fa && (fa.onchange = () => { st.acc = fa.value; tbl.redraw(rows(...r.get())); }); $('.fk', el).onchange = (e) => { st.kind = e.target.value; tbl.redraw(rows(...r.get())); };
    $('.fx', el).onclick = () => CS.exportXLS('hesap-hareketleri', ['Tarih', 'Hesap', 'Açıklama', 'Cari', 'Tür', 'Kategori', 'Tutar'], tbl.rows().map((m) => [CS.date(m.date), CS.account(m.accId)?.name || '', m.desc, CS.contactName(m.cid), KINDS[m.kind] || m.kind || '', m.category || '', m.amt]));
  }
  function moves(body) { moveTable(body); }
  function accDetail(page, a) {
    if (!a) { page.innerHTML = '<div class="blank"><h2>Hesap bulunamadı</h2></div>'; return; }
    const body = CS.head(page, a.name, `<a class="btn" href="#finance">Hesaplara dön</a>${CS.can('finance', 'e') ? CS.btn('Para girişi', 'in', '', 'down') + CS.btn('Para çıkışı', 'out', '', 'up') + CS.btn('Düzenle', 'edit', '', 'edit') : ''}`);
    body.innerHTML = `<div class="kpis">${CS.kpi('Bakiye', money(CS.accBalance(a.id), a.currency), CS.ACC_TYPES[a.type], 'hl')}${CS.kpi('Bu ay giriş', money(mSum(a, 1)))}${CS.kpi('Bu ay çıkış', money(-mSum(a, -1)))}${a.iban ? CS.kpi('IBAN', `<span style="font-size:14px">${esc(a.iban)}</span>`, esc(a.bank || '')) : ''}</div><div id="am"></div>`;
    moveTable($('#am', body), (m) => m.accId === a.id, false, a);
    CS.bind(page, { in: () => ioForm(a.id, 'in'), out: () => ioForm(a.id, 'out'), edit: () => accForm(a) });
  }
  function transfer(body) {
    body.innerHTML = `<div class="grid g2"><section class="panel"><h2>Hesaplar arası virman</h2><p class="muted">Kasadan bankaya para yatırma, bankadan nakit çekme, kredi kartı borcu ödeme, POS’tan bankaya aktarım gibi işlemler.</p><div id="vf"></div><p><button class="btn primary" data-a="go">Virmanı kaydet</button></p></section><section class="panel"><h2>Son virmanlar</h2><div class="list">${CS.db.accMoves.filter((m) => m.kind === 'virman' && m.amt < 0).slice(-15).reverse().map((m) => `<div><span>${CS.date(m.date)} · ${esc(m.desc)}</span><b>${money(-m.amt)}</b></div>`).join('') || '<p class="empty">Virman yok.</p>'}</div></section></div>`;
    const f = CS.form([{ k: 'from', l: 'Çıkış hesabı', t: 'select', opts: CS.accOptions(null), w: 'full' }, { k: 'to', l: 'Giriş hesabı', t: 'select', opts: CS.accOptions(null), w: 'full' }, { k: 'amount', l: 'Tutar', t: 'money', req: true }, { k: 'fee', l: 'Masraf / komisyon', t: 'money' }, { k: 'rate', l: 'Kur (dövizli virmanda)', t: 'number', def: 1 }, { k: 'date', l: 'Tarih', t: 'date', def: CS.today() }, { k: 'desc', l: 'Açıklama', w: 'full' }]);
    $('#vf', body).appendChild(f);
    CS.bind(body, { go: () => { const v = f.read(); if (!v) return; if (v.from === v.to) return CS.toast('Aynı hesap seçilemez.', 'bad'); const ref = 'vir_' + CS.uid(); const d = v.desc || `${CS.account(v.from).name} → ${CS.account(v.to).name}`; CS.addAccMove({ accId: v.from, amt: -v.amount, date: v.date, desc: d, kind: 'virman', ref }); CS.addAccMove({ accId: v.to, amt: v.amount * (CS.num(v.rate) || 1), date: v.date, desc: d, kind: 'virman', ref }); if (v.fee) CS.addAccMove({ accId: v.from, amt: -v.fee, date: v.date, desc: 'Virman masrafı', kind: 'gider', category: 'Komisyon', ref }); CS.log('Virman', d + ' ' + money(v.amount)); CS.save(); CS.toast('Virman kaydedildi.'); CS.route(); } });
  }

  /* ---------- Banka ekstresi içe aktarma ve otomatik eşleştirme ---------- */
  function bank(body) {
    body.innerHTML = `<section class="panel"><h2>Banka hareketlerini içe aktar</h2><p class="muted">Bankanızın internet şubesinden indirdiğiniz hesap hareketlerini (CSV / Excel’den kopyala-yapıştır) yükleyin. Açıklamadaki isim, IBAN ya da vergi numarasına göre cariler otomatik eşleştirilir; onayladıklarınız tahsilat / ödeme / gider olarak işlenir. Daha önce işlenen hareketler tekrar eklenmez.</p>
      <div class="form-grid"><label class="fld third"><span>Banka hesabı</span><select id="ba">${CS.accOptions(['banka', 'vadeli', 'doviz', 'kart', 'pos']).map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join('')}</select></label><label class="fld third"><span>Dosya (CSV)</span><input type="file" id="bf" accept=".csv,.txt"></label><label class="fld third"><span>Tarih biçimi</span><select id="bd"><option value="dmy">GG.AA.YYYY</option><option value="ymd">YYYY-AA-GG</option></select></label><label class="fld full"><span>veya buraya yapıştırın (Tarih, Açıklama, Tutar sütunları; çıkışlar eksi)</span><textarea id="bp" rows="5"></textarea></label></div><p><button class="btn primary" data-a="read">Hareketleri oku ve eşleştir</button></p></section><div id="br" style="margin-top:14px"></div>`;
    CS.bind(body, {
      read: async () => {
        const file = $('#bf', body).files[0]; let rows = file ? CS.parseCSV(await file.text()) : $('#bp', body).value.split(/\r?\n/).map((l) => l.split(/\t|;/));
        rows = rows.filter((r) => r.length >= 3 && r.some((c) => c.trim()));
        const fmt = $('#bd', body).value; const parseD = (s) => { s = String(s).trim(); let m; if ((m = s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})/))) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`; if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/))) return m[0]; return null; };
        const head = rows[0].map((h) => CS.trLower(h)); let iD = head.findIndex((h) => h.includes('tarih')), iA = head.findIndex((h) => h.includes('açıklama') || h.includes('aciklama')), iT = head.findIndex((h) => h.includes('tutar') || h.includes('miktar')), iB = head.findIndex((h) => h.includes('borç') || h.includes('çıkış')), iC = head.findIndex((h) => h.includes('alacak') || h.includes('giriş'));
        const hasHead = iD >= 0; if (!hasHead) { iD = 0; iA = 1; iT = 2; }
        const accId = $('#ba', body).value; const done = new Set(CS.db.accMoves.filter((m) => m.bankKey).map((m) => m.bankKey));
        const items = rows.slice(hasHead ? 1 : 0).map((r) => { const date = parseD(r[iD]); let amt = iT >= 0 ? CS.num(r[iT]) : CS.num(r[iC]) - Math.abs(CS.num(r[iB])); const desc = String(r[iA] ?? '').trim(); const key = accId + '|' + date + '|' + amt + '|' + desc.slice(0, 40); return { date, amt, desc, key, dup: done.has(key) }; }).filter((x) => x.date && x.amt);
        items.forEach((x) => { const D = CS.trLower(x.desc); const c = CS.db.contacts.find((k) => (k.taxNo && D.includes(k.taxNo)) || (k.iban && D.includes(CS.trLower(k.iban.replace(/\s/g, '')))) || (k.name.length > 3 && D.includes(CS.trLower(k.name))) || (k.title && k.title.length > 5 && D.includes(CS.trLower(k.title)))); x.cid = c?.id || ''; x.action = x.cid ? (x.amt > 0 ? 'tahsilat' : 'odeme') : x.amt > 0 ? 'gelir' : 'gider'; x.category = /kira/.test(D) ? 'Kira' : /elektrik|enerjisa|ck boğaziçi|aydem/.test(D) ? 'Elektrik' : /su |iski|aski/.test(D) ? 'Su' : /doğalgaz|igdaş|başkentgaz/.test(D) ? 'Doğalgaz' : /turkcell|vodafone|türk telekom|superonline/.test(D) ? 'İnternet ve telefon' : /sgk/.test(D) ? 'SGK' : /vergi|gib|maliye/.test(D) ? 'Vergi' : /masraf|komisyon|ücret/.test(D) ? 'Komisyon' : /maaş|maas/.test(D) ? 'Maaş' : x.amt > 0 ? 'Diğer gelir' : 'Diğer'; });
        const el = $('#br', body);
        el.innerHTML = `<section class="panel"><h2>${items.length} hareket okundu <small>${items.filter((x) => x.cid).length} cari eşleşti · ${items.filter((x) => x.dup).length} daha önce işlenmiş</small></h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th></th><th>Tarih</th><th>Açıklama</th><th class="r">Tutar</th><th>İşlem</th><th>Cari / kategori</th></tr></thead><tbody>${items.map((x, i) => `<tr class="${x.dup ? 'dim' : ''}"><td><input type="checkbox" data-ok="${i}" ${x.dup ? '' : 'checked'} aria-label="İşle"></td><td>${CS.date(x.date)}</td><td>${esc(x.desc)}</td><td class="r ${x.amt < 0 ? 'neg' : 'pos'}">${CS.fmt2(x.amt)}</td><td><select data-act="${i}">${(x.amt > 0 ? [['tahsilat', 'Cari tahsilat'], ['gelir', 'Gelir']] : [['odeme', 'Cari ödeme'], ['gider', 'Gider']]).map(([k, l]) => `<option value="${k}" ${k === x.action ? 'selected' : ''}>${l}</option>`).join('')}</select></td><td><select data-cid="${i}" style="max-width:200px">${CS.contactOptions(null, '— Cari —').map(([v, l]) => `<option value="${v}" ${v === x.cid ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select> <select data-cat="${i}" style="max-width:150px">${[].concat(CS.db.expenseCats, CS.db.incomeCats).map((c) => `<option ${c === x.category ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><p><button class="btn primary" id="bgo">Seçilenleri işle</button></p></section>`;
        el.addEventListener('change', (e) => { const t = e.target; if (t.dataset.act) items[+t.dataset.act].action = t.value; if (t.dataset.cid != null) items[+t.dataset.cid].cid = t.value; if (t.dataset.cat != null) items[+t.dataset.cat].category = t.value; });
        $('#bgo', el).onclick = () => { let n = 0; $$('[data-ok]', el).forEach((cb) => { if (!cb.checked) return; const x = items[+cb.dataset.ok]; if ((x.action === 'tahsilat' || x.action === 'odeme') && x.cid) { const ref = CS.payment({ dir: x.amt > 0 ? 'in' : 'out', cid: x.cid, accId, amount: Math.abs(x.amt), date: x.date, desc: x.desc, method: 'havale' }); const m = CS.db.accMoves.find((mm) => mm.ref === ref); if (m) m.bankKey = x.key; } else CS.addAccMove({ accId, amt: x.amt, date: x.date, desc: x.desc, kind: x.amt > 0 ? 'gelir' : 'gider', category: x.category, bankKey: x.key }); n++; }); CS.log('Banka ekstresi işlendi', n + ' hareket'); CS.save(); CS.toast(n + ' hareket işlendi.'); CS.go('finance/a/' + accId); };
      }
    });
  }
  function pos(body) {
    const accs = CS.accountsOf(['pos']);
    body.innerHTML = `<p class="muted">Kartlı satışlar önce POS hesabında birikir. Banka hesabınıza geçtiğinde (valör sonrası) komisyon düşülerek aktarın.</p><div class="kpis">${accs.map((a) => CS.kpi(a.name, money(CS.accBalance(a.id)), `Komisyon %${CS.num(a.commission)} · valör ${CS.num(a.settleDays)} gün`)).join('') || '<p class="empty">POS hesabı yok. Hesap ekle > POS / Sanal POS.</p>'}</div>${accs.length ? `<section class="panel"><h2>Bankaya aktar</h2><div id="pf"></div><p><button class="btn primary" data-a="go">Aktarımı kaydet</button></p></section>` : ''}`;
    if (!accs.length) return;
    const f = CS.form([{ k: 'pos', l: 'POS hesabı', t: 'select', opts: accs.map((a) => [a.id, a.name]) }, { k: 'bank', l: 'Banka hesabı', t: 'select', opts: CS.accOptions(['banka']) }, { k: 'amount', l: 'Brüt tutar', t: 'money', def: CS.accBalance(accs[0].id) }, { k: 'comm', l: 'Komisyon %', t: 'number', def: accs[0].commission || 0 }, { k: 'date', l: 'Tarih', t: 'date', def: CS.today() }], { bank: accs[0].settleAcc });
    $('#pf', body).appendChild(f);
    f.addEventListener('change', (e) => { if (e.target.id === 'f_pos') { const a = CS.account(e.target.value); $('#f_amount', f).value = CS.fmt2(CS.accBalance(a.id)); $('#f_comm', f).value = CS.fmt2(a.commission || 0); } });
    CS.bind(body, { go: () => { const v = f.read(); if (!v.amount) return; const ref = 'posv_' + CS.uid(); const fee = CS.round(v.amount * CS.num(v.comm) / 100); CS.addAccMove({ accId: v.pos, amt: -v.amount, date: v.date, desc: 'POS günsonu aktarımı → ' + (CS.account(v.bank)?.name || ''), kind: 'virman', ref }); CS.addAccMove({ accId: v.bank, amt: v.amount, date: v.date, desc: 'POS tahsilatı ← ' + CS.account(v.pos).name, kind: 'virman', ref }); if (fee) CS.addAccMove({ accId: v.bank, amt: -fee, date: v.date, desc: 'POS komisyonu', kind: 'gider', category: 'Komisyon', ref }); CS.log('POS aktarımı', money(v.amount)); CS.save(); CS.toast(`Aktarıldı. Net ${money(v.amount - fee)}, komisyon ${money(fee)}.`); CS.route(); } });
  }

  /* ---------- Nakit akışı projeksiyonu ---------- */
  function flow(body) {
    const t = CS.today(); const days = 90; const ev = [];
    CS.db.docs.filter((d) => ['satis', 'alis'].includes(d.type) && d.status !== 'iptal' && d.cid).forEach((d) => { const rest = CS.round(d.totalTry - CS.docPaid(d)); if (rest > 0.009) ev.push({ date: d.due && d.due > t ? d.due : t, amt: d.type === 'satis' ? rest : -rest, desc: `${d.no} — ${CS.contactName(d.cid)}`, kind: d.type === 'satis' ? 'Fatura tahsilatı' : 'Fatura ödemesi' }); });
    CS.db.cheques.filter((c) => ['portfoy', 'tahsilde', 'verildi'].includes(c.status)).forEach((c) => ev.push({ date: c.due < t ? t : c.due, amt: c.dir === 'alinan' ? c.amount : -c.amount, desc: `${c.kind === 'cek' ? 'Çek' : 'Senet'} ${c.no} — ${CS.contactName(c.cid)}`, kind: c.dir === 'alinan' ? 'Çek/senet tahsili' : 'Çek/senet ödemesi' }));
    CS.db.loans.forEach((l) => (l.inst || []).filter((i) => !i.paid).forEach((i) => ev.push({ date: i.due < t ? t : i.due, amt: -i.amount, desc: `${l.name} taksit ${i.no}`, kind: 'Kredi taksiti' })));
    (CS.db.recurring || []).filter((r) => r.active !== false).forEach((r) => { for (let m = 0; m < 3; m++) { const d = new Date(t); d.setMonth(d.getMonth() + m); d.setDate(Math.min(28, CS.num(r.day) || 1)); const iso = d.toISOString().slice(0, 10); if (iso >= t) ev.push({ date: iso, amt: -CS.num(r.amount), desc: r.name, kind: 'Düzenli gider' }); } });
    CS.db.staff.filter((s) => s.active !== false && s.salary).forEach((s) => { for (let m = 0; m < 3; m++) { const d = new Date(t); d.setMonth(d.getMonth() + m + 1); d.setDate(1); ev.push({ date: d.toISOString().slice(0, 10), amt: -CS.num(s.salary), desc: 'Maaş — ' + s.name, kind: 'Maaş' }); } });
    const start = CS.sum(CS.accountsOf(['kasa', 'banka', 'vadeli', 'pos']), (a) => CS.accBalance(a.id));
    const weeks = []; let run = start; for (let w = 0; w < 13; w++) { const a = CS.addDays(t, w * 7), b = CS.addDays(t, w * 7 + 6); const E = ev.filter((e) => e.date >= a && e.date <= b); const inn = CS.sum(E.filter((e) => e.amt > 0), 'amt'), out = CS.sum(E.filter((e) => e.amt < 0), 'amt'); run += inn + out; weeks.push({ label: CS.date(a).slice(0, 5), value: inn, value2: -out, run, a, b }); }
    body.innerHTML = `<div class="kpis">${CS.kpi('Bugünkü nakit (kasa + banka + POS)', money(start), '', 'hl')}${CS.kpi('90 günde beklenen giriş', money(CS.sum(ev.filter((e) => e.amt > 0 && e.date <= CS.addDays(t, days)), 'amt')))}${CS.kpi('90 günde beklenen çıkış', money(-CS.sum(ev.filter((e) => e.amt < 0 && e.date <= CS.addDays(t, days)), 'amt')))}${CS.kpi('13 hafta sonu tahmini', `<span class="${run < 0 ? 'neg' : ''}">${money(run)}</span>`)}${CS.kpi('Likidite oranı', CS.fmt2((start + CS.sum(ev.filter((e) => e.amt > 0 && e.date <= CS.addDays(t, 30)), 'amt')) / Math.max(1, -CS.sum(ev.filter((e) => e.amt < 0 && e.date <= CS.addDays(t, 30)), 'amt'))), '30 günlük giriş+nakit / çıkış')}</div>
      <section class="panel"><h2>Haftalık beklenen giriş ve çıkış</h2>${CS.barChart(weeks, { two: true, l1: 'Giriş', l2: 'Çıkış' })}<div class="tbl-wrap" style="margin-top:10px"><table class="tbl"><tr><th>Hafta</th><th class="r">Giriş</th><th class="r">Çıkış</th><th class="r">Dönem sonu nakit</th></tr>${weeks.map((w) => `<tr><td>${CS.date(w.a)} – ${CS.date(w.b)}</td><td class="r pos">${CS.fmt2(w.value)}</td><td class="r neg">${CS.fmt2(w.value2)}</td><td class="r"><b class="${w.run < 0 ? 'neg' : ''}">${CS.fmt2(w.run)}</b></td></tr>`).join('')}</table></div></section>
      <section class="panel" style="margin-top:14px"><h2>Beklenen hareketler</h2><div id="ft"></div></section>`;
    CS.table($('#ft', body), { rows: ev.sort((a, b) => a.date.localeCompare(b.date)), cols: [{ l: 'Tarih', k: 'date', f: (e) => CS.date(e.date) }, { l: 'Tür', k: 'kind' }, { l: 'Açıklama', k: 'desc' }, { l: 'Tutar', a: 'r', v: (e) => e.amt, f: (e) => `<span class="${e.amt < 0 ? 'neg' : 'pos'}">${CS.fmt2(e.amt)}</span>` }] });
  }

  /* ================= ÇEK, SENET, KREDİ ================= */
  const CH_ST = { portfoy: 'Portföyde', tahsilde: 'Bankada tahsilde', teminat: 'Teminatta', tahsil: 'Tahsil edildi', ciro: 'Ciro edildi', karsiliksiz: 'Karşılıksız / protestolu', iade: 'İade edildi', verildi: 'Verildi (ödenecek)', odendi: 'Ödendi', iptal: 'İptal' };
  CS.CH_ST = CH_ST;
  CS.mod('cheques', {
    title: 'Çek, senet, kredi',
    render(page, prm) {
      const sub = prm._[0] || 'in';
      const body = CS.head(page, 'Çek, senet, kredi', CS.can('cheques', 'e') ? CS.btn('Çek / senet al', 'nin', 'primary', 'down') + CS.btn('Çek / senet ver', 'nout', '', 'up') + CS.btn('Kredi ekle', 'nl', '', 'plus') : '', [['in', 'Alınan çek ve senetler', 'cheques'], ['out', 'Verilen çek ve senetler', 'cheques/out'], ['loans', 'Krediler', 'cheques/loans'], ['cal', 'Vade takvimi', 'cheques/cal']], sub);
      CS.bind(page, { nin: () => chequeForm('alinan'), nout: () => chequeForm('verilen'), nl: () => loanForm() });
      if (sub === 'loans') return loans(body);
      if (sub === 'cal') return cal(body);
      chList(body, sub === 'in' ? 'alinan' : 'verilen');
    }
  });
  function chList(body, dir) {
    const all = CS.db.cheques.filter((c) => c.dir === dir); const t = CS.today();
    const open = all.filter((c) => (dir === 'alinan' ? ['portfoy', 'tahsilde', 'teminat'] : ['verildi']).includes(c.status));
    body.innerHTML = `<div class="kpis">${CS.kpi(dir === 'alinan' ? 'Portföy + tahsilde' : 'Ödenecek', money(CS.sum(open, 'amount')), open.length + ' adet', 'hl')}${CS.kpi('Vadesi geçmiş', money(CS.sum(open.filter((c) => c.due < t), 'amount')), open.filter((c) => c.due < t).length + ' adet')}${CS.kpi('30 gün içinde', money(CS.sum(open.filter((c) => c.due >= t && c.due <= CS.addDays(t, 30)), 'amount')))}${CS.kpi('Ortalama vade', open.length ? Math.round(CS.sum(open, (c) => CS.daysBetween(t, c.due) * c.amount) / Math.max(1, CS.sum(open, 'amount'))) + ' gün' : '—')}${dir === 'alinan' ? CS.kpi('Karşılıksız', money(CS.sum(all.filter((c) => c.status === 'karsiliksiz'), 'amount'))) : ''}</div><div id="cht"></div>`;
    CS.table($('#cht', body), {
      rows: all.slice().sort((a, b) => a.due.localeCompare(b.due)), ph: 'Çek no, cari, banka…', searchText: (c) => [c.no, c.bank, c.drawer, CS.contactName(c.cid), CS.contactName(c.toCid), CH_ST[c.status]].join(' '),
      cols: [{ l: 'Vade', k: 'due', f: (c) => `<span class="${c.due < t && ['portfoy', 'tahsilde', 'verildi'].includes(c.status) ? 'neg' : ''}">${CS.date(c.due)}</span>` }, { l: 'Tür', v: (c) => (c.kind === 'cek' ? 'Çek' : 'Senet') }, { l: 'No / banka', v: (c) => c.no, f: (c) => `<b>${esc(c.no || '—')}</b><small>${esc([c.bank, c.branch].filter(Boolean).join(' · '))}</small>` }, { l: 'Cari', v: (c) => CS.contactName(c.cid), f: (c) => esc(CS.contactName(c.cid)) + (c.toCid ? `<small>Ciro: ${esc(CS.contactName(c.toCid))}</small>` : '') + (c.drawer ? `<small>Keşideci: ${esc(c.drawer)}</small>` : '') }, { l: 'Tutar', a: 'r', v: (c) => c.amount, f: (c) => `<b>${money(c.amount, c.currency)}</b>` }, { l: 'Durum', v: (c) => CH_ST[c.status], f: (c) => `<span class="pill ${['tahsil', 'odendi'].includes(c.status) ? 'ok' : c.status === 'karsiliksiz' ? 'bad' : ['portfoy', 'verildi'].includes(c.status) ? 'info' : ''}">${CH_ST[c.status]}</span>` }],
      onRow: (c) => chequeDetail(c), actions: (c) => CS.actBtn('st', 'İşlem', 'swap'), onAct: (a, c) => chequeDetail(c)
    });
  }
  function chequeForm(dir) {
    const f = CS.form([{ k: 'kind', l: 'Tür', t: 'select', opts: [['cek', 'Çek'], ['senet', 'Senet']] }, { k: 'cid', l: dir === 'alinan' ? 'Alınan cari' : 'Verilen cari', t: 'select', opts: CS.contactOptions(null), req: true }, { k: 'no', l: 'Çek / senet no' }, { k: 'amount', l: 'Tutar', t: 'money', req: true }, { k: 'date', l: 'İşlem tarihi', t: 'date', def: CS.today() }, { k: 'due', l: 'Vade tarihi', t: 'date', req: true }, { k: 'bank', l: 'Banka' }, { k: 'branch', l: 'Şube' }, { k: 'account', l: 'Hesap no' }, { k: 'drawer', l: 'Keşideci / borçlu' }, { k: 'currency', l: 'Döviz', t: 'select', opts: CS.CURRENCIES }, { k: 'place', l: 'Keşide yeri' }, { k: 'note', l: 'Not', w: 'full' }]);
    CS.modal({ title: dir === 'alinan' ? 'Çek / senet al' : 'Çek / senet ver', body: f, buttons: [{ label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; CS.addCheque({ ...v, dir }); CS.log('Çek/senet kaydı', `${v.no} ${money(v.amount)}`); CS.save(); CS.route(); } }] });
  }
  function chequeDetail(c) {
    const acts = c.dir === 'alinan' ? { portfoy: [['tahsilde', 'Bankaya tahsile ver'], ['tahsil', 'Tahsil edildi (kasa/banka)'], ['ciro', 'Ciro et (tedarikçiye ver)'], ['teminat', 'Teminata ver'], ['karsiliksiz', 'Karşılıksız çıktı'], ['iade', 'Müşteriye iade et']], tahsilde: [['tahsil', 'Tahsil edildi'], ['karsiliksiz', 'Karşılıksız çıktı'], ['portfoy', 'Portföye geri al']], teminat: [['portfoy', 'Portföye geri al']], karsiliksiz: [['tahsil', 'Sonradan tahsil edildi']] }[c.status] || [] : { verildi: [['odendi', 'Ödendi (hesaptan çıktı)'], ['iade', 'Geri alındı / iptal']] }[c.status] || [];
    const m = CS.modal({ title: `${c.kind === 'cek' ? 'Çek' : 'Senet'} ${c.no || ''} — ${money(c.amount)}`, body: `<div class="list">${[['Cari', CS.contactName(c.cid)], ['Vade', CS.date(c.due)], ['Banka', [c.bank, c.branch, c.account].filter(Boolean).join(' · ')], ['Keşideci', c.drawer], ['Durum', CH_ST[c.status]], ['Ciro edilen', CS.contactName(c.toCid)], ['Not', c.note]].filter((x) => x[1]).map(([k, v]) => `<div><span class="muted">${k}</span><b>${esc(v)}</b></div>`).join('')}</div><h3>Geçmiş</h3><div class="timeline">${c.history.map((h) => `<div>${CS.date(h.date)} · ${esc(CH_ST[h.status] || h.status)}<br><span class="muted">${esc(h.note || '')}</span></div>`).join('')}</div>${acts.length && CS.can('cheques', 'e') ? `<h3>İşlem yap</h3><div class="form-grid"><label class="fld third"><span>Tarih</span><input type="date" id="cd" value="${CS.today()}"></label><label class="fld third"><span>Hesap (tahsil/ödeme)</span><select id="ca">${CS.accOptions(['banka', 'kasa']).map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join('')}</select></label><label class="fld third"><span>Ciro edilecek cari</span><select id="cc">${CS.contactOptions('tedarikci').map(([v, l]) => `<option value="${v}">${esc(l)}</option>`).join('')}</select></label></div><div class="row" style="margin-top:10px">${acts.map(([k, l]) => `<button class="btn sm" data-ch="${k}">${l}</button>`).join('')}</div>` : ''}`, buttons: [{ label: 'Bordro yazdır', onClick: () => { CS.printHTML(`<h1>${c.dir === 'alinan' ? 'Çek/senet giriş bordrosu' : 'Çek/senet çıkış bordrosu'}</h1><p>${esc(CS.contactName(c.cid))} · ${CS.date(c.date)}</p><table><tr><th>Tür</th><th>No</th><th>Banka</th><th>Vade</th><th class="r">Tutar</th></tr><tr><td>${c.kind === 'cek' ? 'Çek' : 'Senet'}</td><td>${esc(c.no)}</td><td>${esc(c.bank || '')}</td><td>${CS.date(c.due)}</td><td class="r">${CS.fmt2(c.amount)}</td></tr></table><br><table><tr><td>Teslim eden</td><td>Teslim alan</td></tr></table>`, 'Bordro'); return false; } }, ...(CS.can('cheques', 'd') ? [{ label: 'Sil', kind: 'danger', onClick: () => { CS.db.cheques = CS.db.cheques.filter((x) => x !== c); CS.removeLedgerByRef(c.id); CS.removeLedgerByRef(c.id + '_ciro'); CS.removeLedgerByRef(c.id + '_kz'); CS.removeAccMovesByRef(c.id + '_t'); CS.save(); CS.route(); } }] : []), { label: 'Kapat' }] });
    m.el.addEventListener('click', (e) => {
      const b = e.target.closest('[data-ch]'); if (!b) return; const ns = b.dataset.ch; const date = $('#cd', m.el).value; const acc = $('#ca', m.el).value; let note = b.textContent;
      if (ns === 'tahsil' || ns === 'odendi') { CS.addAccMove({ accId: acc, amt: c.dir === 'alinan' ? c.amount : -c.amount, date, desc: `${c.kind === 'cek' ? 'Çek' : 'Senet'} ${c.dir === 'alinan' ? 'tahsilatı' : 'ödemesi'} ${c.no} — ${CS.contactName(c.cid)}`, kind: 'cek', ref: c.id + '_t' }); note += ' · ' + CS.account(acc)?.name; }
      if (ns === 'karsiliksiz' || (ns === 'iade' && c.dir === 'alinan')) { CS.addLedger({ cid: c.cid, amt: c.amount, date, desc: `${c.kind === 'cek' ? 'Çek' : 'Senet'} ${ns === 'iade' ? 'iadesi' : 'karşılıksız'} ${c.no}`, ref: c.id + '_kz', kind: 'cek' }); }
      if (ns === 'iade' && c.dir === 'verilen') { CS.addLedger({ cid: c.cid, amt: -c.amount, date, desc: `Verilen ${c.kind === 'cek' ? 'çek' : 'senet'} geri alındı ${c.no}`, ref: c.id + '_kz', kind: 'cek' }); }
      if (ns === 'ciro') { const to = $('#cc', m.el).value; if (!to) return CS.toast('Ciro edilecek cariyi seçin.', 'bad'); c.toCid = to; CS.addLedger({ cid: to, amt: c.amount, date, desc: `Çek ciro ${c.no}`, ref: c.id + '_ciro', kind: 'cek' }); note += ' · ' + CS.contactName(to); }
      if (ns === 'tahsilde') c.collectAcc = acc;
      c.status = ns; c.history.push({ date, status: ns, note }); CS.log('Çek/senet durumu', `${c.no}: ${CH_ST[ns]}`); CS.save(); m.close(); CS.route(); CS.refreshBadges();
    });
  }
  function cal(body) {
    const t = CS.today(); const ev = [].concat(CS.db.cheques.filter((c) => ['portfoy', 'tahsilde', 'verildi', 'teminat'].includes(c.status)).map((c) => ({ date: c.due, t: `${c.kind === 'cek' ? 'Çek' : 'Senet'} ${c.no} — ${CS.contactName(c.cid)}`, a: c.dir === 'alinan' ? c.amount : -c.amount })), CS.db.loans.flatMap((l) => (l.inst || []).filter((i) => !i.paid).map((i) => ({ date: i.due, t: `${l.name} taksit ${i.no}`, a: -i.amount }))));
    const months = CS.groupBy(ev.sort((a, b) => a.date.localeCompare(b.date)), (e) => e.date.slice(0, 7));
    body.innerHTML = Object.entries(months).map(([m, E]) => `<section class="panel" style="margin-bottom:12px"><h2>${CS.monthName(m)} <small>Giriş ${money(CS.sum(E.filter((e) => e.a > 0), 'a'))} · Çıkış ${money(-CS.sum(E.filter((e) => e.a < 0), 'a'))}</small></h2><div class="list">${E.map((e) => `<div><span class="${e.date < t ? 'neg' : ''}">${CS.date(e.date)} · ${esc(e.t)}</span><b class="${e.a < 0 ? 'neg' : 'pos'}">${CS.fmt2(e.a)}</b></div>`).join('')}</div></section>`).join('') || '<p class="empty">Açık vade yok.</p>';
  }
  function loans(body) {
    body.innerHTML = '<div id="lt"></div>';
    CS.table($('#lt', body), { rows: CS.db.loans, empty: 'Kredi yok.', cols: [{ l: 'Kredi', v: (l) => l.name, f: (l) => `<b>${esc(l.name)}</b><small>${esc(l.bank || '')} · faiz %${CS.fmt2(l.rate)} aylık</small>` }, { l: 'Başlangıç', k: 'start', f: (l) => CS.date(l.start) }, { l: 'Anapara', a: 'r', v: (l) => l.amount, f: (l) => CS.fmt2(l.amount) }, { l: 'Taksit', a: 'r', v: (l) => (l.inst || []).length, f: (l) => `${l.inst.filter((i) => i.paid).length} / ${l.inst.length}` }, { l: 'Kalan borç', a: 'r', v: (l) => CS.sum(l.inst.filter((i) => !i.paid), 'amount'), f: (l) => `<b>${CS.fmt2(CS.sum(l.inst.filter((i) => !i.paid), 'amount'))}</b>` }, { l: 'Sonraki taksit', v: (l) => l.inst.find((i) => !i.paid)?.due || '', f: (l) => { const i = l.inst.find((x) => !x.paid); return i ? `<span class="${i.due < CS.today() ? 'neg' : ''}">${CS.date(i.due)} · ${CS.fmt2(i.amount)}</span>` : '<span class="pill ok">Kapandı</span>'; } }], onRow: (l) => loanDetail(l) });
  }
  function loanForm() {
    const f = CS.form([{ k: 'name', l: 'Kredi adı', req: true }, { k: 'bank', l: 'Banka' }, { k: 'amount', l: 'Kredi tutarı', t: 'money', req: true }, { k: 'rate', l: 'Aylık faiz %', t: 'number' }, { k: 'n', l: 'Taksit sayısı', t: 'number', req: true, def: 12 }, { k: 'start', l: 'Kullanım tarihi', t: 'date', def: CS.today() }, { k: 'first', l: 'İlk taksit tarihi', t: 'date', def: CS.addDays(CS.today(), 30) }, { k: 'bsmv', l: 'BSMV / KKDF % (faize)', t: 'number', def: 5 }, { k: 'accId', l: 'Paranın yattığı hesap', t: 'select', opts: CS.accOptions(['banka'], '— Hesaba işleme —') }, { k: 'fee', l: 'Tahsis ücreti', t: 'money' }]);
    CS.modal({ title: 'Yeni kredi', body: f, buttons: [{ label: 'Vazgeç' }, { label: 'Ödeme planını oluştur', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; const r = CS.num(v.rate) / 100 * (1 + CS.num(v.bsmv) / 100); const n = Math.max(1, Math.round(v.n)); const pay = r ? (v.amount * r) / (1 - Math.pow(1 + r, -n)) : v.amount / n; const inst = []; let bal = v.amount; for (let i = 1; i <= n; i++) { const int = bal * r; const princ = pay - int; bal -= princ; const d = new Date(v.first + 'T12:00:00'); d.setMonth(d.getMonth() + i - 1); inst.push({ no: i, due: d.toISOString().slice(0, 10), amount: CS.round(pay), principal: CS.round(princ), interest: CS.round(int), paid: false }); } const l = { id: 'l_' + CS.uid(), name: v.name, bank: v.bank, amount: v.amount, rate: v.rate, start: v.start, accId: v.accId, inst }; CS.db.loans.push(l); if (v.accId) { CS.addAccMove({ accId: v.accId, amt: v.amount, date: v.start, desc: 'Kredi kullanımı — ' + v.name, kind: 'kredi', ref: l.id }); if (v.fee) CS.addAccMove({ accId: v.accId, amt: -v.fee, date: v.start, desc: 'Kredi tahsis ücreti', kind: 'gider', category: 'Komisyon', ref: l.id }); } CS.log('Kredi eklendi', v.name); CS.save(); CS.route(); loanDetail(l); } }] });
  }
  function loanDetail(l) {
    const m = CS.modal({ title: l.name, size: 'lg', body: `<div class="tbl-wrap"><table class="tbl"><tr><th>#</th><th>Vade</th><th class="r">Anapara</th><th class="r">Faiz</th><th class="r">Taksit</th><th>Durum</th><th></th></tr>${l.inst.map((i, k) => `<tr><td>${i.no}</td><td class="${!i.paid && i.due < CS.today() ? 'neg' : ''}">${CS.date(i.due)}</td><td class="r">${CS.fmt2(i.principal)}</td><td class="r">${CS.fmt2(i.interest)}</td><td class="r"><b>${CS.fmt2(i.amount)}</b></td><td>${i.paid ? `<span class="pill ok">Ödendi ${CS.date(i.paidDate)}</span>` : '<span class="pill warn">Bekliyor</span>'}</td><td>${!i.paid && CS.can('cheques', 'e') ? `<button class="btn sm" data-pay="${k}">Öde</button>` : ''}</td></tr>`).join('')}<tr><td colspan="4"><b>Toplam</b></td><td class="r"><b>${CS.fmt2(CS.sum(l.inst, 'amount'))}</b></td><td colspan="2">Faiz toplamı ${CS.fmt2(CS.sum(l.inst, 'interest'))}</td></tr></table></div><label class="fld" style="margin-top:10px;max-width:300px"><span>Ödeme hesabı</span><select id="la">${CS.accOptions(['banka', 'kasa']).map(([v, x]) => `<option value="${v}" ${v === l.accId ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select></label>`, buttons: [...(CS.can('cheques', 'd') ? [{ label: 'Krediyi sil', kind: 'danger', onClick: () => { CS.db.loans = CS.db.loans.filter((x) => x !== l); CS.removeAccMovesByRef(l.id); l.inst.forEach((i) => CS.removeAccMovesByRef(l.id + '_' + i.no)); CS.save(); CS.route(); } }] : []), { label: 'Kapat' }] });
    m.el.addEventListener('click', (e) => { const b = e.target.closest('[data-pay]'); if (!b) return; const i = l.inst[+b.dataset.pay]; i.paid = true; i.paidDate = CS.today(); CS.addAccMove({ accId: $('#la', m.el).value, amt: -i.amount, desc: `${l.name} taksit ${i.no}`, kind: 'kredi', category: 'Kredi taksiti', ref: l.id + '_' + i.no }); CS.log('Kredi taksiti ödendi', `${l.name} #${i.no}`); CS.save(); m.close(); loanDetail(l); CS.refreshBadges(); });
  }

  /* ================= GELİR VE GİDER ================= */
  CS.mod('expenses', {
    title: 'Gelir ve gider',
    render(page, prm) {
      const sub = prm._[0] || 'list';
      const body = CS.head(page, 'Gelir ve gider', CS.can('expenses', 'e') ? CS.btn('Gider ekle', 'ng', 'primary', 'plus') + CS.btn('Gelir ekle', 'ni', '', 'plus') + CS.btn('Fiş / fatura fotoğrafı', 'scan', '', 'cam') : '', [['list', 'Gelir ve giderler', 'expenses'], ['summary', 'Kategori özeti', 'expenses/summary'], ['recurring', 'Düzenli giderler', 'expenses/recurring'], ['assets', 'Demirbaşlar', 'expenses/assets'], ['projects', 'Projeler', 'expenses/projects'], ['cats', 'Kategoriler', 'expenses/cats']], sub);
      CS.bind(page, { ng: () => expenseForm('gider'), ni: () => expenseForm('gelir'), scan: () => expenseForm('gider', true) });
      ({ list: expList, summary, recurring, assets, projects, cats: expCats })[sub](body, prm);
    }
  });
  function expList(body) { moveTable(body, (m) => ['gider', 'gelir'].includes(m.kind) || (m.kind === 'kredi' && m.amt < 0)); }
  function expenseForm(kind, photo) {
    const f = CS.form([{ k: 'category', l: 'Kategori', t: 'select', opts: kind === 'gider' ? CS.db.expenseCats : CS.db.incomeCats }, { k: 'amount', l: 'Tutar (KDV dahil)', t: 'money', req: true }, { k: 'kdv', l: 'KDV %', t: 'select', opts: CS.KDV_RATES.map(String), def: '20' }, { k: 'date', l: 'Tarih', t: 'date', def: CS.today() }, { k: 'accId', l: kind === 'gider' ? 'Ödendiği hesap' : 'Yattığı hesap', t: 'select', opts: CS.accOptions(null) }, { k: 'docNo', l: 'Belge / fiş no' }, { k: 'supplier', l: 'Firma / kişi' }, { k: 'staffId', l: 'Personel (maaş/avans/prim)', t: 'select', opts: CS.staffOptions() }, { k: 'projectId', l: 'Proje', t: 'select', opts: CS.projOptions() }, { k: 'branchId', l: 'Şube', t: 'select', opts: CS.db.branches.map((b) => [b.id, b.name]) }, { k: 'desc', l: 'Açıklama', w: 'full' }], { branchId: CS.branchId || CS.user.branchId });
    const box = document.createElement('div'); box.append(f); const ex = document.createElement('div'); ex.style.marginTop = '10px';
    ex.innerHTML = `<label class="btn sm">${icon('cam', 15)} Fiş / fatura fotoğrafı ekle<input type="file" accept="image/*" capture="environment" id="ef" hidden></label> <img id="ep" style="max-height:80px;display:none;border-radius:6px;vertical-align:middle"> <span class="muted">Fotoğraf belge arşivi olarak gidere eklenir.</span>`; box.append(ex);
    let image = ''; $('#ef', ex).onchange = (e) => { const file = e.target.files[0]; if (file) CS.resizeImage(file, 900, (u) => { image = u; const p = $('#ep', ex); p.src = u; p.style.display = ''; }); };
    if (photo) setTimeout(() => $('#ef', ex).click(), 200);
    CS.modal({ title: kind === 'gider' ? 'Gider ekle' : 'Gelir ekle', body: box, buttons: [{ label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; if (!v.accId) { CS.toast('Hesap seçin.', 'bad'); return false; } const kdvAmt = CS.round(v.amount - v.amount / (1 + CS.num(v.kdv) / 100)); CS.addAccMove({ accId: v.accId, amt: kind === 'gider' ? -v.amount : v.amount, date: v.date, desc: v.desc || `${v.category}${v.supplier ? ' — ' + v.supplier : ''}`, kind, category: v.category, kdv: CS.num(v.kdv), kdvAmt, docNo: v.docNo, supplier: v.supplier, staffId: v.staffId, projectId: v.projectId, branchId: v.branchId, image }); CS.log(kind === 'gider' ? 'Gider eklendi' : 'Gelir eklendi', `${v.category}: ${money(v.amount)}`); CS.save(); CS.toast('Kaydedildi.'); CS.route(); } }] });
  }
  CS.expenseForm = expenseForm;
  function summary(body) {
    body.innerHTML = '<div id="rng" style="margin-bottom:10px"></div><div id="sm"></div>';
    const draw = (a, b) => { const L = CS.db.accMoves.filter((m) => ['gider', 'gelir'].includes(m.kind) && m.date >= a && m.date <= b); const g = CS.groupBy(L.filter((m) => m.kind === 'gider'), (m) => m.category || 'Diğer'); const i = CS.groupBy(L.filter((m) => m.kind === 'gelir'), (m) => m.category || 'Diğer'); const sales = CS.sum(CS.saleLines(a, b), 'net'), cogs = CS.sum(CS.saleLines(a, b), 'cost'); const gT = -CS.sum(L.filter((m) => m.kind === 'gider'), 'amt'), iT = CS.sum(L.filter((m) => m.kind === 'gelir'), 'amt'); const maxG = Math.max(1, ...Object.values(g).map((x) => -CS.sum(x, 'amt')));
      $('#sm', body).innerHTML = `<div class="kpis">${CS.kpi('Net satış (KDV hariç)', money(sales))}${CS.kpi('Satılan malın maliyeti', money(cogs))}${CS.kpi('Brüt kâr', money(sales - cogs), '', 'hl')}${CS.kpi('Diğer gelirler', money(iT))}${CS.kpi('Giderler', money(gT))}${CS.kpi('Net kâr (yaklaşık)', `<span class="${sales - cogs + iT - gT < 0 ? 'neg' : 'pos'}">${money(sales - cogs + iT - gT)}</span>`)}</div><div class="grid g2"><section class="panel"><h2>Giderler kategoriye göre</h2><div class="bars-h">${Object.entries(g).map(([k, L2]) => ({ k, v: -CS.sum(L2, 'amt') })).sort((x, y) => y.v - x.v).map((x) => `<div><span>${esc(x.k)}</span><i style="width:${(x.v / maxG) * 100}%"></i><span>${CS.fmt2(x.v)}</span></div>`).join('') || '<p class="empty">Gider yok.</p>'}</div></section><section class="panel"><h2>Gelirler kategoriye göre</h2><div class="list">${Object.entries(i).map(([k, L2]) => `<div><span>${esc(k)}</span><b>${CS.fmt2(CS.sum(L2, 'amt'))}</b></div>`).join('') || '<p class="empty">Gelir yok.</p>'}</div><h2 style="margin-top:14px">Gider KDV’si (indirilecek)</h2><p><b>${money(CS.sum(L.filter((m) => m.kind === 'gider'), (m) => CS.num(m.kdvAmt)))}</b></p></section></div>`; };
    const r = CS.dateRange($('#rng', body), draw); draw(...r.get());
  }
  function recurring(body) {
    CS.db.recurring = CS.db.recurring || [];
    body.innerHTML = `<p class="muted">Kira, aidat, abonelik gibi her ay tekrar eden giderleri tanımlayın. Nakit akışı tahmininde kullanılır; vadesi gelenleri tek tıkla gider olarak işleyebilirsiniz.</p><p>${CS.btn('Düzenli gider ekle', 'n', 'primary', 'plus')}</p><div id="rt"></div>`;
    const edit = (r) => { const f = CS.form([{ k: 'name', l: 'Ad', req: true }, { k: 'category', l: 'Kategori', t: 'select', opts: CS.db.expenseCats }, { k: 'amount', l: 'Tutar', t: 'money', req: true }, { k: 'day', l: 'Ayın kaçında', t: 'number', def: 1 }, { k: 'accId', l: 'Ödeme hesabı', t: 'select', opts: CS.accOptions(null) }, { k: 'active', l: 'Aktif', t: 'check', def: true }], r || { active: true }); CS.modal({ title: 'Düzenli gider', size: 'sm', body: f, buttons: [{ label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; if (r) Object.assign(r, v); else CS.db.recurring.push({ id: CS.uid(), ...v, last: '' }); CS.save(); CS.route(); } }] }); };
    CS.bind(body, { n: () => edit() });
    const ym = CS.today().slice(0, 7);
    CS.table($('#rt', body), { rows: CS.db.recurring, empty: 'Düzenli gider yok.', search: false, cols: [{ l: 'Ad', k: 'name' }, { l: 'Kategori', k: 'category' }, { l: 'Gün', a: 'r', k: 'day' }, { l: 'Tutar', a: 'r', v: (r) => r.amount, f: (r) => CS.fmt2(r.amount) }, { l: 'Bu ay', v: (r) => (r.last === ym ? 'İşlendi' : 'Bekliyor'), f: (r) => (r.last === ym ? '<span class="pill ok">İşlendi</span>' : '<span class="pill warn">Bekliyor</span>') }], actions: (r) => (r.last !== ym ? CS.actBtn('run', 'Bu ayı işle', 'check') : '') + CS.actBtn('edit', 'Düzenle', 'edit') + CS.actBtn('del', 'Sil', 'trash', 'danger'), onAct: (a, r) => { if (a === 'edit') edit(r); if (a === 'del') { CS.db.recurring = CS.db.recurring.filter((x) => x !== r); CS.save(); CS.route(); } if (a === 'run') { CS.addAccMove({ accId: r.accId || CS.db.accounts[0].id, amt: -r.amount, desc: r.name, kind: 'gider', category: r.category }); r.last = ym; CS.save(); CS.route(); } } });
  }
  function assets(body) {
    body.innerHTML = `<p>${CS.can('expenses', 'e') ? CS.btn('Demirbaş ekle', 'n', 'primary', 'plus') : ''}</p><div id="at"></div>`;
    const dep = (a) => { const yrs = Math.max(0, CS.daysBetween(a.date, CS.today()) / 365); const life = CS.num(a.life) || 5; const acc = Math.min(1, yrs / life) * CS.num(a.cost); return { acc, net: CS.num(a.cost) - acc, yearly: CS.num(a.cost) / life }; };
    const edit = (a) => { const f = CS.form([{ k: 'name', l: 'Demirbaş adı', req: true }, { k: 'code', l: 'Demirbaş kodu' }, { k: 'serial', l: 'Seri no / plaka' }, { k: 'date', l: 'Alış tarihi', t: 'date', def: CS.today() }, { k: 'cost', l: 'Alış bedeli (KDV hariç)', t: 'money', req: true }, { k: 'life', l: 'Faydalı ömür (yıl)', t: 'number', def: 5 }, { k: 'location', l: 'Bulunduğu yer' }, { k: 'staffId', l: 'Zimmetli personel', t: 'select', opts: CS.staffOptions() }, { k: 'supplier', l: 'Satıcı' }, { k: 'warranty', l: 'Garanti bitişi', t: 'date' }, { k: 'status', l: 'Durum', t: 'select', opts: ['Kullanımda', 'Arızalı', 'Depoda', 'Satıldı', 'Hurdaya ayrıldı'] }, { k: 'note', l: 'Not', w: 'full' }], a || {}); CS.modal({ title: a ? 'Demirbaş düzenle' : 'Yeni demirbaş', body: f, buttons: [...(a ? [{ label: 'Sil', kind: 'danger', onClick: () => { CS.db.assets = CS.db.assets.filter((x) => x !== a); CS.save(); CS.route(); } }] : []), { label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; if (a) Object.assign(a, v); else CS.db.assets.push({ id: 'as_' + CS.uid(), ...v }); CS.save(); CS.route(); } }] }); };
    CS.bind(body, { n: () => edit() });
    CS.table($('#at', body), { rows: CS.db.assets, empty: 'Demirbaş kaydı yok.', cols: [{ l: 'Demirbaş', v: (a) => a.name, f: (a) => `<b>${esc(a.name)}</b><small>${esc([a.code, a.serial].filter(Boolean).join(' · '))}</small>` }, { l: 'Alış', k: 'date', f: (a) => CS.date(a.date) }, { l: 'Yer / zimmet', v: (a) => a.location || '', f: (a) => esc(a.location || '') + (a.staffId ? `<small>${esc(CS.byId('staff', a.staffId)?.name || '')}</small>` : '') }, { l: 'Durum', v: (a) => a.status || 'Kullanımda' }, { l: 'Maliyet', a: 'r', v: (a) => CS.num(a.cost), f: (a) => CS.fmt2(a.cost) }, { l: 'Birikmiş amortisman', a: 'r', v: (a) => dep(a).acc, f: (a) => CS.fmt2(dep(a).acc) }, { l: 'Net değer', a: 'r', v: (a) => dep(a).net, f: (a) => `<b>${CS.fmt2(dep(a).net)}</b>` }], onRow: edit, foot: (rs) => `<tr><td colspan="4">Toplam</td><td class="r">${CS.fmt2(CS.sum(rs, (a) => CS.num(a.cost)))}</td><td class="r">${CS.fmt2(CS.sum(rs, (a) => dep(a).acc))}</td><td class="r">${CS.fmt2(CS.sum(rs, (a) => dep(a).net))}</td></tr>` });
  }
  CS.assetNet = (a) => { const yrs = Math.max(0, CS.daysBetween(a.date, CS.today()) / 365); const life = CS.num(a.life) || 5; return CS.num(a.cost) - Math.min(1, yrs / life) * CS.num(a.cost); };
  function projStats(p) { const docs = CS.db.docs.filter((d) => d.projectId === p.id && d.status !== 'iptal'); const sales = CS.sum(docs.filter((d) => ['satis', 'pos'].includes(d.type)), 'net'); const cogs = CS.sum(docs.filter((d) => ['satis', 'pos'].includes(d.type)).flatMap((d) => d.lines), (l) => CS.num(l.qty) * CS.num(l.cost)); const buys = CS.sum(docs.filter((d) => d.type === 'alis'), 'net'); const mv = CS.db.accMoves.filter((m) => m.projectId === p.id); const inc = CS.sum(mv.filter((m) => m.kind === 'gelir'), 'amt'); const exp = -CS.sum(mv.filter((m) => m.kind === 'gider'), 'amt'); const prod = CS.sum(CS.db.productions.filter((r) => r.projectId === p.id), (r) => r.material + r.labor); const cashIn = CS.sum(mv.filter((m) => m.amt > 0), 'amt'), cashOut = -CS.sum(mv.filter((m) => m.amt < 0), 'amt'); return { sales, cogs, buys, inc, exp, prod, profit: sales - cogs + inc - exp, cashIn, cashOut, docs }; }
  function projects(body) {
    body.innerHTML = `<p>${CS.can('expenses', 'e') ? CS.btn('Proje ekle', 'n', 'primary', 'plus') : ''}</p><p class="muted">Faturalara, giderlere, tahsilatlara ve üretim kayıtlarına proje atayarak her işin kârlılığını ve nakit akışını ayrı izleyin.</p><div id="pt"></div>`;
    const edit = (p) => { const f = CS.form([{ k: 'name', l: 'Proje adı', req: true }, { k: 'cid', l: 'Müşteri', t: 'select', opts: CS.contactOptions('musteri') }, { k: 'status', l: 'Durum', t: 'select', opts: [['aktif', 'Aktif'], ['beklemede', 'Beklemede'], ['tamam', 'Tamamlandı'], ['iptal', 'İptal']] }, { k: 'budget', l: 'Bütçe', t: 'money' }, { k: 'start', l: 'Başlangıç', t: 'date' }, { k: 'end', l: 'Bitiş', t: 'date' }, { k: 'manager', l: 'Sorumlu', t: 'select', opts: CS.staffOptions() }, { k: 'note', l: 'Not', w: 'full' }], p || { status: 'aktif', start: CS.today() }); CS.modal({ title: p ? 'Proje' : 'Yeni proje', body: f, buttons: [{ label: 'Vazgeç' }, { label: 'Kaydet', kind: 'primary', onClick: () => { const v = f.read(); if (!v) return false; if (p) Object.assign(p, v); else CS.db.projects.push({ id: 'pr_' + CS.uid(), ...v }); CS.save(); CS.route(); } }] }); };
    CS.bind(body, { n: () => edit() });
    CS.table($('#pt', body), { rows: CS.db.projects, empty: 'Proje yok.', cols: [{ l: 'Proje', v: (p) => p.name, f: (p) => `<b>${esc(p.name)}</b><small>${esc(CS.contactName(p.cid))}</small>` }, { l: 'Durum', v: (p) => ({ aktif: 'Aktif', beklemede: 'Beklemede', tamam: 'Tamamlandı', iptal: 'İptal' })[p.status] }, { l: 'Satış', a: 'r', v: (p) => projStats(p).sales, f: (p) => CS.fmt2(projStats(p).sales) }, { l: 'Maliyet + gider', a: 'r', v: (p) => projStats(p).cogs + projStats(p).exp, f: (p) => CS.fmt2(projStats(p).cogs + projStats(p).exp + projStats(p).prod) }, { l: 'Kâr', a: 'r', v: (p) => projStats(p).profit, f: (p) => `<b class="${projStats(p).profit < 0 ? 'neg' : 'pos'}">${CS.fmt2(projStats(p).profit)}</b>` }, { l: 'Bütçe kullanımı', a: 'r', v: (p) => (p.budget ? (projStats(p).cogs + projStats(p).exp) / p.budget : 0), f: (p) => (p.budget ? '%' + CS.fmt2(((projStats(p).cogs + projStats(p).exp + projStats(p).prod) / p.budget) * 100) : '—') }], onRow: (p) => { const s = projStats(p); CS.modal({ title: p.name, size: 'lg', body: `<div class="kpis">${CS.kpi('Satış', money(s.sales))}${CS.kpi('Satılan mal maliyeti', money(s.cogs))}${CS.kpi('Proje giderleri', money(s.exp))}${CS.kpi('Üretim maliyeti', money(s.prod))}${CS.kpi('Kâr', money(s.profit), '', 'hl')}${CS.kpi('Nakit giriş / çıkış', money(s.cashIn - s.cashOut), `${CS.fmt2(s.cashIn)} / ${CS.fmt2(s.cashOut)}`)}</div><h3>Belgeler</h3><div class="list">${s.docs.map((d) => `<div><a href="#docs/view/${d.id}" onclick="this.closest('.modal-wrap').remove()">${esc(d.no)} · ${esc(CS.DOC_TYPES[d.type].short)}</a><b>${money(d.total)}</b></div>`).join('') || '<p class="muted">Yok.</p>'}</div>`, buttons: [{ label: 'Düzenle', onClick: () => edit(p) }, { label: 'Kapat' }] }); } });
  }
  function expCats(body) {
    body.innerHTML = `<div class="grid g2">${[['expenseCats', 'Gider kategorileri'], ['incomeCats', 'Gelir kategorileri']].map(([k, l]) => `<section class="panel"><h2>${l}</h2><div class="list">${CS.db[k].map((c, i) => `<div><span>${esc(c)}</span><button class="icon-btn danger" data-d="${k}:${i}" aria-label="Sil">${icon('trash', 15)}</button></div>`).join('')}</div><div class="row" style="margin-top:8px"><input id="n_${k}" placeholder="Yeni kategori" style="flex:1"><button class="btn" data-add="${k}">Ekle</button></div></section>`).join('')}</div>`;
    body.addEventListener('click', (e) => { const d = e.target.closest('[data-d]'), a = e.target.closest('[data-add]'); if (d) { const [k, i] = d.dataset.d.split(':'); CS.db[k].splice(+i, 1); CS.save(); CS.route(); } if (a) { const v = $('#n_' + a.dataset.add, body).value.trim(); if (v) { CS.db[a.dataset.add].push(v); CS.save(); CS.route(); } } });
  }
})();
